-- Workload A: money moves. Native = relational transaction.
-- Why: two rows must change atomically, concurrent writers conflict.
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 'a1';
UPDATE accounts SET balance = balance + 100 WHERE id = 'a2';
COMMIT;
-- Trade-off accepted: single-shard coordination cost, harder write sharding.

-- Workload B: feed ingest. Native = partitioned append, not join.
-- Why: 100k writes/sec, reads are "latest N in partition".
CREATE TABLE events (
  user_id   TEXT,
  event_ts  TIMESTAMPTZ,
  payload   JSONB,
  PRIMARY KEY ((user_id), event_ts)
) WITH partition_by = 'user_id';
-- Trade-off accepted: no cross-partition ACID, app owns secondary lookups.

-- Workload C: product search. Native = inverted index, not LIKE '%...%'.
-- SELECT * FROM products WHERE name LIKE '%red shoe%'; -- full scan, dies at scale
-- Move to search engine: tokenize, rank, facet. Trade-off: index lag + dual-write ops.
